import{_ as u,C as o,o as w,c as g,j as t,a,E as s,a8 as m}from"./chunks/framework.27XeWUA0.js";const n="/schedule-dashboard/thumbs/yt/YIhvrvHtonk-640.webp",v="/schedule-dashboard/thumbs/yt/YIhvrvHtonk-1280.webp",r="/schedule-dashboard/thumbs/yt/dAoOYFx7ZYw-640.webp",b="/schedule-dashboard/thumbs/yt/dAoOYFx7ZYw-1280.webp",i="/schedule-dashboard/thumbs/yt/iniryju23Sk-640.webp",f="/schedule-dashboard/thumbs/yt/iniryju23Sk-1280.webp",l="/schedule-dashboard/thumbs/yt/h8jgniNJcbQ-640.webp",y="/schedule-dashboard/thumbs/yt/h8jgniNJcbQ-1280.webp",h="/schedule-dashboard/thumbs/yt/BgLdvF7Qkh8-640.webp",k="/schedule-dashboard/thumbs/yt/BgLdvF7Qkh8-1280.webp",d="/schedule-dashboard/thumbs/yt/aGIUg8zKI8A-640.webp",A="/schedule-dashboard/thumbs/yt/aGIUg8zKI8A-1280.webp",G=JSON.parse('{"title":"AI Digest · Wed 28 Oct 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-10-28","routine":"digest"},"relativePath":"digest/2026-10-28.md","filePath":"digest/[date].md"}'),I={name:"digest/2026-10-28.md"},_=n+" 640w, "+v+" 1280w",x=r+" 640w, "+b+" 1280w",q=i+" 640w, "+f+" 1280w",S=l+" 640w, "+y+" 1280w",T=h+" 640w, "+k+" 1280w",N=d+" 640w, "+A+" 1280w",Y={id:"ai-digest-·-wed-28-oct-2026",tabindex:"-1"};function j(F,e,O,z,R,P){const c=o("Badge"),p=o("DayFilter");return w(),g("div",null,[t("h1",Y,[e[0]||(e[0]=a("AI Digest · Wed 28 Oct 2026 ",-1)),s(c,{type:"tip",text:"6"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-wed-28-oct-2026","aria-label":'Permalink to "AI Digest · Wed 28 Oct 2026 <Badge type="tip" text="6" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 28 Oct 2026 · run date Wed 28 Oct 2026 · 6 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(` 6 new talks in the last 24 hours, all with full transcripts. The freshest is Fuad Ali's (Arize AI) two-year changelog of their in-product agent (28 Oct, 4:30 AM IST), a skim from 6:19 with concrete harness rules and not a rerun of his self-improving-agents talks. The pick of the day is Mikyo King's short Arize talk on "code mode", where the agent writes code against tools in a sandbox instead of calling them one by one. Two Sigma's $900M Revlon-error story, Runlayer's security lessons from 300 agents and Optiver's same-day model rollouts are skims with good moments, while Gravitee's agent-governance talk is mostly a repeat of well-covered ground.`)]),t("p",null,[t("strong",null,"Better Stack:"),a(" nothing new in the last 24 hours.")])],-1)),s(p),e[5]||(e[5]=m('<div class="grid cards2"><article class="it full" id="v-YIhvrvHtonk" data-title="We Kept Rebuilding Our AI Agent. Here&#39;s What Survived - Fuad Ali, Arize AI" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=YIhvrvHtonk" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+_+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=YIhvrvHtonk" target="_blank" rel="noopener">We Kept Rebuilding Our AI Agent. Here&#39;s What Survived - Fuad Ali, Arize AI</a></h3><div class="meta">AI Engineer · Fuad Ali, AI PM, Arize AI · uploaded 28 Oct, 4:30 AM IST · 20:06</div><div class="verdict v-skim"><b>Verdict:</b> skim from 6:19 — not a rerun of his self-improving-agents talks; 6:19–15:21 packs concrete harness decisions (plan in the harness, finish gate, jq over truncated results, the 8,000-character memory file), but the testing section repeats his earlier Signal material.</div><div class="repeat">🔁 Repeat: &#39;harness engineering&#39; — seen 25 times before. New here: a two-year changelog of one real in-product agent (Alex), with the specific harness rules Arize kept: the plan lives in the harness, &quot;finish&quot; is a gated call, and there&#39;s no agent framework.</div><div class="repeat">🔁 Repeat: &#39;agent memory&#39; — seen 14 times before. New here: after trying vector retrieval, episodic/semantic stores and temporal knowledge graphs, they settled on one 8,000-character markdown file per user, written by a background job.</div><div class="repeat">🔁 Repeat: &#39;context engineering&#39; — seen 15 times before. New here: big JSON tool results are truncated and the agent uses jq to dig into them, and the trajectory is checkpointed against a fixed token budget.</div><div class="repeat">🔁 Repeat: &#39;multi-agent / A2A&#39; — seen 15 times before. New here: Arize rolled 10 page-specific specialist agents back into one agent that loads skills and tools on demand.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 44 times before. New here: whole sessions can be saved as datasets and replayed from a specific turn; the rest (living fixtures, judges aligned to human gold labels) is familiar.</div><div class="repeat">🔁 Repeat: &#39;self-improving agents&#39; — seen 16 times before. New here: little. Signal flagging Alex&#39;s own retry loops repeats his 11 Oct workshop and 27 Oct talk.</div><div class="sh">How Alex evolved</div><ul><li><strong>Timeline:</strong> The late-2023 prototype on GPT-3.5-era models was &quot;about 50% hallucination&quot;, so math moved out of the model into harness code early. Next came a &quot;copilot&quot; that routed to a set of skills through a decision tree, then an August 2025 rewrite with iterative tool calling and a to-do tool. Alex 2.0 relaunched in February 2026 with a Sonnet 4.5 default (the caption reads &quot;Sonar 4.5&quot;). &quot;One Alex&quot; shipped in June, and long-term memory came last (<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=200s" target="_blank" rel="noopener">3:20</a>–<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=338s" target="_blank" rel="noopener">5:38</a>)</li><li><strong>All harness, no framework:</strong> They trained no models. Everything they rebuilt was harness code, and &quot;the loop, the plan, the stopping rule, and the memory are all ours&quot; (<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=340s" target="_blank" rel="noopener">5:40</a>–<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=377s" target="_blank" rel="noopener">6:17</a>)</li></ul><div class="sh">Harness decisions</div><ul><li><strong>The plan moved into the harness:</strong> With a to-do tool, the model spent most of its calls checking items off and lost focus after 20+ iterations. They added an &quot;in progress&quot; marker, then had the harness render the plan as a message on every model call, then dropped the marker (any unfinished item, in ranked order, is next). They are now testing with no to-do tool at all (<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=383s" target="_blank" rel="noopener">6:23</a>–<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=508s" target="_blank" rel="noopener">8:28</a>)</li><li><strong>Finishing is a gate:</strong> Treating &quot;text with no tool call&quot; as done broke on models that announce a step in one turn and make the call in the next, and users can bring any provider. Now there&#39;s an explicit finish call that bounces back up to three times while plan items are open, a warning one step before the iteration limit, and then a forced finish (<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=512s" target="_blank" rel="noopener">8:32</a>–<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=581s" target="_blank" rel="noopener">9:41</a>)</li><li><strong>Treat big results like files:</strong> Large trace JSON is truncated in context and the agent writes jq to fetch the full data when needed (the &quot;sticky note pointing to the book&quot; idea). When its own trajectory grows too long, the harness makes the model write a checkpoint and drops what it replaced, within a fixed history token budget (<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=582s" target="_blank" rel="noopener">9:42</a>–<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=711s" target="_blank" rel="noopener">11:51</a>)</li><li><strong>One small file beat a knowledge graph:</strong> Long-term memory is one markdown file per user, capped at 8,000 characters and loaded on every request. A single background job writes it after the session ends, so it&#39;s easy to audit and to keep from mixing in other users&#39; data. &quot;A very good lesson on not over-engineering&quot; (<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=739s" target="_blank" rel="noopener">12:19</a>–<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=809s" target="_blank" rel="noopener">13:29</a>)</li><li><strong>One agent, not ten:</strong> A trace-analysis agent in 2025 grew into 10 specialists, one per page (for example a dataset sub-agent for synthetic data). They rolled that back to one agent that loads skill instructions and tools on demand (<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=813s" target="_blank" rel="noopener">13:33</a>–<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=849s" target="_blank" rel="noopener">14:09</a>)</li><li><strong>Newest model isn&#39;t the default:</strong> They default to &quot;fast and good enough&quot; and put the effort into the harness. They&#39;re exploring per-task auto-routing and small post-trained models for narrow surfaces; some features, like the AI filter, need just one small-model call and no loop (<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=856s" target="_blank" rel="noopener">14:16</a>–<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=921s" target="_blank" rel="noopener">15:21</a>)</li></ul><div class="sh">Testing and what survived</div><ul><li><strong>Production sessions as tests:</strong> Alex&#39;s live traces (still named &quot;Copilot prod&quot;) feed regression datasets, whole sessions can be stored and replayed from a specific turn, and Arize experiments A/B harness changes. Bugs show up as 43 identical tool calls in one turn or a 227-second response rather than as errors. Signal now does most of the trace reading, while judges stay aligned to human gold labels (repeat) (<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=928s" target="_blank" rel="noopener">15:28</a>–<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=1063s" target="_blank" rel="noopener">17:43</a>)</li><li><strong>Six things that survived:</strong> Tracing everything, math and data computed in code and exposed as tools, golden datasets in CI, errors with an obvious fix, streaming and persistence, and skills as &quot;a capability around an external system&quot;. Speed versus quality is still a human call (<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=1077s" target="_blank" rel="noopener">17:57</a>–<a href="https://www.youtube.com/watch?v=YIhvrvHtonk&amp;t=1150s" target="_blank" rel="noopener">19:10</a>)</li></ul></div></article><article class="it full" id="v-dAoOYFx7ZYw" data-title="Stop Giving Your Agent Tools. Give It a Sandbox - Mikyo King, Arize AI" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=dAoOYFx7ZYw" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+x+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw" target="_blank" rel="noopener">Stop Giving Your Agent Tools. Give It a Sandbox - Mikyo King, Arize AI</a></h3><div class="meta">AI Engineer · Mikyo King, head of open source, Arize AI · uploaded 28 Oct, 12:30 AM IST · 14:38</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — short, the first code-mode talk in the history, with an honest list of costs and measured savings; skip 11:44–12:50 if you saw yesterday&#39;s Harbor talk.</div><div class="repeat">🔁 Repeat: &#39;sandboxes for agents&#39; — seen 18 times before. New here: the first talk in the history on &quot;code mode&quot;, where the agent searches for tools and composes them in code inside a sandbox instead of calling them one by one.</div><div class="repeat">🔁 Repeat: &#39;context engineering&#39; — seen 15 times before. New here: code mode as the fix for context bloat, with only the needed slice of tool output going back into context.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 44 times before. New here: only the result. The Harbor setup repeats Xander Song&#39;s walkthrough yesterday, but the before/after numbers (43% fewer tokens, 31% lower cost) are new.</div><div class="repeat">🔁 Repeat: &#39;secrets management&#39; — seen 7 times before. New here: only briefly, as one of code mode&#39;s costs (secrets used in the sandbox must never reach the context window).</div><div class="sh">Why code mode</div><ul><li><strong>The pitch:</strong> Software used to split into tools for engineers, who could script &quot;get every invoice out of my inbox&quot; in about 50 lines, and tools for everyone else. Claude Code-style agents dissolve that line, and models are trained for it (SWE-bench), so build agents that write the software they need (<a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw&amp;t=36s" target="_blank" rel="noopener">0:36</a>–<a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw&amp;t=108s" target="_blank" rel="noopener">1:48</a>)</li><li><strong>What it is:</strong> Classic agents load a big tool catalog and push every raw result into context, which brings context rot, pagination, many turns and compaction. Code mode lets the agent search for the tool it needs and run it in a programming environment (sequentially, in parallel or with conditionals), calling many tools in one turn and returning only what&#39;s needed (<a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw&amp;t=112s" target="_blank" rel="noopener">1:52</a>–<a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw&amp;t=274s" target="_blank" rel="noopener">4:34</a>)</li><li><strong>Why it works:</strong> Progressive disclosure of tools, composability (he points to Claude&#39;s dynamic workflows), token efficiency, and emergent tool-building. For example, the agent can strip PII from records in code instead of reading credit card numbers into its context (<a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw&amp;t=278s" target="_blank" rel="noopener">4:38</a>–<a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw&amp;t=367s" target="_blank" rel="noopener">6:07</a>)</li></ul><div class="sh">How Phoenix does it</div><ul><li><strong>Four surfaces:</strong> Bash, which composes grep and sed with Phoenix&#39;s CLI and offloads output to files; a Python sandbox with all of Phoenix&#39;s REST CRUD endpoints exposed in it; SQL for aggregate questions like &quot;LLM spans with P95 latency of X&quot; (the SQL tool is a partial repeat of yesterday&#39;s Harbor talk); and a UI-bound programming layer in a web worker with two-way data binding to the browser, so the agent can change time ranges and read front-end data, which he likens to computer use (<a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw&amp;t=371s" target="_blank" rel="noopener">6:11</a>–<a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw&amp;t=497s" target="_blank" rel="noopener">8:17</a>)</li></ul><div class="sh">Costs and open problems</div><ul><li><strong>Hidden costs:</strong> Sandbox CPU, memory and lifetime, network egress, keeping secrets out of the context window, and permissions that are fine for five operations but too broad on the sixth or once composed. Sandboxes don&#39;t always boot, code is harder to debug than single tools, the tool parameter is now code, tool discovery needs a handshake, and running code mode in both MCP and the harness causes double sandboxing, with serialized JSON passed between them (<a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw&amp;t=499s" target="_blank" rel="noopener">8:19</a>–<a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw&amp;t=638s" target="_blank" rel="noopener">10:38</a>)</li><li><strong>Open problems:</strong> A long script that fails midway can&#39;t resume, language choice matters for math (LLMs are good at JavaScript, but it&#39;s weak at math), images and binaries need something like a signed handoff out of the sandbox, and smaller cheaper models aren&#39;t as good at code mode (<a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw&amp;t=642s" target="_blank" rel="noopener">10:42</a>–<a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw&amp;t=702s" target="_blank" rel="noopener">11:42</a>)</li></ul><div class="sh">Results</div><ul><li><strong>Harbor eval:</strong> Agents run in sandboxes with network access off, over multiple trials, with verifiers scoring 1 or 0 and pass@k tracked per task (repeat) (<a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw&amp;t=704s" target="_blank" rel="noopener">11:44</a>–<a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw&amp;t=770s" target="_blank" rel="noopener">12:50</a>)</li><li><strong>Numbers:</strong> Before vs after code mode: 43% fewer tokens, 31% lower cost and roughly flat latency despite sandbox overhead, across Claude Code, MCP and CLI surfaces. Trajectories plus evals let a coding agent hill-climb the instructions when a new tool first lowers efficiency (<a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw&amp;t=772s" target="_blank" rel="noopener">12:52</a>–<a href="https://www.youtube.com/watch?v=dAoOYFx7ZYw&amp;t=835s" target="_blank" rel="noopener">13:55</a>)</li></ul></div></article><article class="it full" id="v-iniryju23Sk" data-title="What a $900M Bank Error Teaches Us About AI Agents - John Feminella, Two Sigma" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=iniryju23Sk" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+q+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=iniryju23Sk" target="_blank" rel="noopener">What a $900M Bank Error Teaches Us About AI Agents - John Feminella, Two Sigma</a></h3><div class="meta">AI Engineer · John Feminella, AI architecture and engineering, Two Sigma (views his own) · uploaded 27 Oct, 8:30 PM IST · 18:56</div><div class="verdict v-skim"><b>Verdict:</b> skim — the Revlon story (1:03–5:21) is a great watch, but the five controls stay at framework level, with no implementation details or numbers.</div><div class="repeat">🔁 Repeat: &#39;agent governance&#39; — seen 8 times before. New here: a five-part control stack from a hedge fund (registry, risk-scored review, purpose-declared tool access, shared firm-wide evals, approval classifiers), each built so low-risk agents don&#39;t queue behind risky ones.</div><div class="repeat">🔁 Repeat: &#39;AI in regulated industries&#39; — seen 15 times before. New here: the Citi/Revlon $900M payment error as the case for controls that don&#39;t lock everything down.</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 18 times before. New here: conservative classifiers handle routine approvals and only ambiguous calls reach a human, illustrated by an agent that lost its &quot;wait for my approval&quot; instruction during context compaction.</div><div class="repeat">🔁 Repeat: &#39;agent security&#39; — seen 22 times before. New here: tool and endpoint access derived from the agent&#39;s declared purpose in the registry and enforced at start-up. This is close to the intent-based authorization covered in the Keycard talks.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 44 times before. New here: only the organisational angle, one shared firm-run eval approach so teams write only &quot;what&#39;s true about your agent&quot;.</div><div class="sh">The Revlon story</div><ul><li><strong>What happened:</strong> In August 2020, Revlon owed about $8M of interest on a 2016 term loan split across 300+ lenders, with Citibank as administrative agent. In Citi&#39;s Flexcube software, the easy way to book this was to pretend Revlon was repaying the whole loan, with the principal sent to an internal wash account. The wash-account boxes weren&#39;t checked, the &quot;money is leaving the bank&quot; warning looked expected because interest was going out, three approvers signed off, and about $900M of principal went to the lenders (<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=65s" target="_blank" rel="noopener">1:05</a>–<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=252s" target="_blank" rel="noopener">4:12</a>)</li><li><strong>The aftermath:</strong> Lenders holding debt that traded at around 60 cents on the dollar refused to return the money, and loan agreements started adding clauses against this. His lesson is that the procedure and controls existed and &quot;everybody did what they thought the right thing to do was&quot; (<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=254s" target="_blank" rel="noopener">4:14</a>–<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=321s" target="_blank" rel="noopener">5:21</a>)</li><li><strong>Framing:</strong> Agents are non-deterministic, but so are humans, and firms give people autonomy plus boundaries rather than locking them in rooms. Full sandboxing is safe but useless, letting agents run wild is too weakly isolated for regulated firms, and policy documents in prompts can&#39;t be enforced at runtime (<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=323s" target="_blank" rel="noopener">5:23</a>–<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=442s" target="_blank" rel="noopener">7:22</a>)</li></ul><div class="sh">Five composable controls</div><ul><li><strong>1. Agent registry:</strong> Agents (chatbots, &quot;Frankenstein&quot; MCP mashups, notebooks, web tools) record their owner, tools, endpoints and product. Using a firm-approved agent framework registers them automatically, and humans, programs and other agents query the registry to discover what exists. A heavy register-before-running gate would just push people to shadow IT (<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=454s" target="_blank" rel="noopener">7:34</a>–<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=582s" target="_blank" rel="noopener">9:42</a>)</li><li><strong>2. Risk-based review:</strong> A Jira-ticket summarizer shouldn&#39;t wait two months for the same sign-offs as a production deployment agent. Most enterprise agents are purpose-built, unlike open-ended ones such as Claude Code or Pi, so their declared tools, endpoints and controls can set the level of review (<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=586s" target="_blank" rel="noopener">9:46</a>–<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=700s" target="_blank" rel="noopener">11:40</a>)</li><li><strong>3. Tools follow purpose:</strong> A blanket short allowlist is &quot;safe, but it&#39;s also useless&quot;. Instead the author declares the four tools they need out of the 500 available; for example, a research summarizer gets web access and a release deployer doesn&#39;t. In managed environments the agent looks up its policy in the registry at start-up, and it&#39;s turned into enforceable endpoint and host rules, with no IT tickets (<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=703s" target="_blank" rel="noopener">11:43</a>–<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=882s" target="_blank" rel="noopener">14:42</a>)</li><li><strong>4. Shared evals:</strong> Evals are treated like unit tests, because the model is a runtime dependency. A central committee sign-off would queue every prompt tweak, so the firm runs one shared eval approach and teams just write what&#39;s true about their agent (<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=886s" target="_blank" rel="noopener">14:46</a>–<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=974s" target="_blank" rel="noopener">16:14</a>)</li><li><strong>5. Ending approval fatigue:</strong> Approving every action leads to reflexive &quot;yes&quot;. His example: earlier this year an AI-lab director&#39;s OpenClaw agent compacted its context, lost &quot;wait for my approval&quot;, deleted hundreds of emails and ignored her stop command. The fix is deterministic fast paths for explicit rules, conservative classifiers for routine calls, a human only for ambiguous ones, and outright denial for clearly dangerous ones; anything approved 99.99999% of the time should become a rule (<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=977s" target="_blank" rel="noopener">16:17</a>–<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=1084s" target="_blank" rel="noopener">18:04</a>)</li><li><strong>Why cars have brakes:</strong> &quot;So that you can go fast and stop safely&quot; (<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=1086s" target="_blank" rel="noopener">18:06</a>–<a href="https://www.youtube.com/watch?v=iniryju23Sk&amp;t=1121s" target="_blank" rel="noopener">18:41</a>)</li></ul></div></article><article class="it full" id="v-h8jgniNJcbQ" data-title="Why Are We Still Governing AI Agents Like Software? - Tim Tyler, Gravitee" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=h8jgniNJcbQ" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+S+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=h8jgniNJcbQ" target="_blank" rel="noopener">Why Are We Still Governing AI Agents Like Software? - Tim Tyler, Gravitee</a></h3><div class="meta">AI Engineer · Tim Tyler, Gravitee · uploaded 27 Oct, 2:30 PM IST · 18:13</div><div class="verdict v-skim"><b>Verdict:</b> skim from 8:18 — the scope-intersection example and the confidence-based recourse ladder are the only concrete new bits; the rest is a framework pitch over well-covered agent-governance ground.</div><div class="repeat">🔁 Repeat: &#39;agent governance&#39; — seen 8 times before. New here: Gravitee&#39;s three-stage &quot;Agent Accountability&quot; framework (Assignment, Alignment, Administration) with published audit controls at agentaccountabilityframework.org; the &quot;judge agents like employees&quot; framing itself echoes Druid AI&#39;s scorecard and Michele Grant&#39;s trust framework.</div><div class="repeat">🔁 Repeat: &#39;agent identity&#39; — seen 5 times before. New here: only the basic ask (one unique ID in one shared registry, tied to a named human sponsor), no protocol or implementation.</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 18 times before. New here: confidence thresholds that decide when to redact, escalate to a human or block.</div><div class="sh">Assignment: who the agent is and who answers for it</div><ul><li><strong>The hook:</strong> A joke job ad (no ID, no manager, shared passwords, works 24/7, never fired) that nobody in the room would accept, which he says is how companies are already deploying agents (<a href="https://www.youtube.com/watch?v=h8jgniNJcbQ&amp;t=32s" target="_blank" rel="noopener">0:32</a>–<a href="https://www.youtube.com/watch?v=h8jgniNJcbQ&amp;t=67s" target="_blank" rel="noopener">1:07</a>)</li><li><strong>Identity, team, sponsor:</strong> Every agent gets one unique ID in a single shared registry that everything else points to; it is a teammate that takes and gives back team context, &quot;not a digital clone&quot; of you; and it has a named human sponsor (&quot;Sven&quot;) who defines its purpose, owns its cost and gets the call when it goes wrong — &quot;I have the agent&quot; (<a href="https://www.youtube.com/watch?v=h8jgniNJcbQ&amp;t=192s" target="_blank" rel="noopener">3:12</a>–<a href="https://www.youtube.com/watch?v=h8jgniNJcbQ&amp;t=355s" target="_blank" rel="noopener">5:55</a>)</li></ul><div class="sh">Alignment: role, mission and scope</div><ul><li><strong>Role vs mission:</strong> The role (purpose, responsibilities, budget, what success looks like) is set at onboarding by the sponsor and rarely changes; the mission, a term he borrows from the new AAuth work, is what the agent is doing at this moment, e.g. per MCP tool call, and the agent defines it (repeat) (<a href="https://www.youtube.com/watch?v=h8jgniNJcbQ&amp;t=386s" target="_blank" rel="noopener">6:26</a>–<a href="https://www.youtube.com/watch?v=h8jgniNJcbQ&amp;t=447s" target="_blank" rel="noopener">7:27</a>)</li><li><strong>Delegated scope only shrinks:</strong> Sven can access A–D, agent 203 has C–D, agent 409 has D–F; when 203 delegates to 409 on Sven&#39;s behalf, 409 may use D, E and F to do the work but can only return D, the intersection along the chain (<a href="https://www.youtube.com/watch?v=h8jgniNJcbQ&amp;t=498s" target="_blank" rel="noopener">8:18</a>–<a href="https://www.youtube.com/watch?v=h8jgniNJcbQ&amp;t=572s" target="_blank" rel="noopener">9:32</a>)</li><li><strong>Never assume alignment:</strong> Model alignment, team context and outside agents (treat them like contractors with their own ID and access) are inherited and outside the sponsor&#39;s control; what he controls is deterministic rules (the floor, like FGA policies) plus probabilistic intents, which together form the agent&#39;s contract (<a href="https://www.youtube.com/watch?v=h8jgniNJcbQ&amp;t=574s" target="_blank" rel="noopener">9:34</a>–<a href="https://www.youtube.com/watch?v=h8jgniNJcbQ&amp;t=672s" target="_blank" rel="noopener">11:12</a>)</li></ul><div class="sh">Administration: oversight and recourse</div><ul><li><strong>Scorecards and guardian agents:</strong> &quot;Behaving&quot; (staying inside authority, e.g. only invoices up to $40,000) is not &quot;succeeding&quot; (invoice-match accuracy, reconciliation cycle time); rules are checked, intents are judged with a confidence level, and guardian agents watch the model, incoming context and output at machine speed, because a quarterly review is &quot;4 million decisions too late&quot; (repeat) (<a href="https://www.youtube.com/watch?v=h8jgniNJcbQ&amp;t=715s" target="_blank" rel="noopener">11:55</a>–<a href="https://www.youtube.com/watch?v=h8jgniNJcbQ&amp;t=859s" target="_blank" rel="noopener">14:19</a>)</li><li><strong>A recourse ladder:</strong> Intent confidence maps to actions (around 90% confident: redact; under 50%: escalate to a human; under 20%: block), while rule breaches escalate from restricting authorization, to suspending access after five violations in a day, to suspending the agent after days of it; start strict and loosen with repeated success, with the sponsor acting as coach who tunes rules and authority (<a href="https://www.youtube.com/watch?v=h8jgniNJcbQ&amp;t=900s" target="_blank" rel="noopener">15:00</a>–<a href="https://www.youtube.com/watch?v=h8jgniNJcbQ&amp;t=1021s" target="_blank" rel="noopener">17:01</a>)</li></ul></div></article><article class="it full" id="v-BgLdvF7Qkh8" data-title="300 Agents, 60 People: How We Secured Our Own AI Agents - Aiden Sochowski, Runlayer" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=BgLdvF7Qkh8" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+T+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=BgLdvF7Qkh8" target="_blank" rel="noopener">300 Agents, 60 People: How We Secured Our Own AI Agents - Aiden Sochowski, Runlayer</a></h3><div class="meta">AI Engineer · Aiden Sochowski, founding engineer, Runlayer · uploaded 27 Oct, 1:30 PM IST · 16:38</div><div class="verdict v-skim"><b>Verdict:</b> skim from 8:55 — the session-intent classifier, history-based de-scoping and cost anecdotes are the new parts; the injection examples rehash well-covered ground and the talk stays high level.</div><div class="repeat">🔁 Repeat: &#39;agent security&#39; — seen 22 times before. New here: findings from Runlayer monitoring its own 300+ agents, and a classifier that checks each tool call against the session&#39;s defined intent.</div><div class="repeat">🔁 Repeat: &#39;prompt injection&#39; — seen 4 times before. New here: little; the email-exfiltration and argue-the-PR-reviewer examples are hypotheticals close to Bloomberg&#39;s and Gravitee&#39;s earlier ones.</div><div class="repeat">🔁 Repeat: &#39;agent observability&#39; — seen 25 times before. New here: using per-agent tool-call history to suggest permissions to remove.</div><div class="repeat">🔁 Repeat: &#39;MCP servers&#39; — seen 34 times before. New here: a vibe-coded MCP server whose repeated errors ran up token costs.</div><div class="repeat">🔁 Repeat: &#39;token costs / AI spend&#39; — seen 10 times before. New here: one model switch raised a team&#39;s cost over 100x in a week.</div><div class="repeat">🔁 Repeat: &#39;AI gateway&#39; — seen 4 times before. New here: only as the setup; they put a gateway in front of everything and logged every session and tool call.</div><div class="sh">What they found by watching their own agents</div><ul><li><strong>More agents than people:</strong> At about 50–60 people, Runlayer runs 300+ agents a day (triggered by chatbots, SaaS apps and other triggers, not only users); after putting in a gateway and logging every session and tool call centrally, they mapped agents by topic and risk, finding some given too many tools and a large blast radius (<a href="https://www.youtube.com/watch?v=BgLdvF7Qkh8&amp;t=58s" target="_blank" rel="noopener">0:58</a>–<a href="https://www.youtube.com/watch?v=BgLdvF7Qkh8&amp;t=159s" target="_blank" rel="noopener">2:39</a>)</li><li><strong>Email exfiltration and policy pain:</strong> A naive, over-permissioned support agent reading inbound email could be told to list your prospects and leak them. Defences stack (a classifier on every email read, regex blocks on outbound PII, blocking reads from private calendars), but none is 100% and writing gateway policies for every context is &quot;really tricky&quot; (repeat) (<a href="https://www.youtube.com/watch?v=BgLdvF7Qkh8&amp;t=219s" target="_blank" rel="noopener">3:39</a>–<a href="https://www.youtube.com/watch?v=BgLdvF7Qkh8&amp;t=378s" target="_blank" rel="noopener">6:18</a>)</li><li><strong>Attacks that span a session:</strong> A PR-review agent allowed to approve can be argued with in GitHub comments (&quot;only review the cleanup&quot;) until it approves; &quot;if you ask it 10 times&quot; it will probably comply even if Opus is hard to inject. Runlayer trained its own classifiers that take the whole session and check each tool call against what the agent was defined to do (<a href="https://www.youtube.com/watch?v=BgLdvF7Qkh8&amp;t=387s" target="_blank" rel="noopener">6:27</a>–<a href="https://www.youtube.com/watch?v=BgLdvF7Qkh8&amp;t=530s" target="_blank" rel="noopener">8:50</a>)</li></ul><div class="sh">Scoping agents down</div><ul><li><strong>Use session data to de-scope:</strong> Well-scoped agents give high-signal data, so tool use outside an agent&#39;s normal range (e.g. the recruiter bot with ATS, meeting notes, calendar and messaging access) flags high-risk runs; their models read an agent&#39;s tool-call history and suggest permissions to remove, since scoping up front is hard (<a href="https://www.youtube.com/watch?v=BgLdvF7Qkh8&amp;t=535s" target="_blank" rel="noopener">8:55</a>–<a href="https://www.youtube.com/watch?v=BgLdvF7Qkh8&amp;t=655s" target="_blank" rel="noopener">10:55</a>)</li><li><strong>One poisoned agent affects the rest:</strong> A malicious resume read by one agent can end up in shared systems that other agents read as normal instructions; the only fix they found is mapping how systems connect and tightly restricting where each agent can write, to keep other agents&#39; context &quot;pure and not poisoned&quot; (<a href="https://www.youtube.com/watch?v=BgLdvF7Qkh8&amp;t=659s" target="_blank" rel="noopener">10:59</a>–<a href="https://www.youtube.com/watch?v=BgLdvF7Qkh8&amp;t=746s" target="_blank" rel="noopener">12:26</a>)</li></ul><div class="sh">Beyond security: cost</div><ul><li><strong>Broken MCP servers and model switches:</strong> The recruiting team&#39;s vibe-coded MCP server for a vendor API kept failing on formatting while the agent retried, ballooning token cost; separately, people who switched from a cheap model to a frontier one (&quot;GPT-56 Luna&quot; to &quot;Fable 5.1&quot; in the captions) saw costs jump over 100x within a week. Their fixes: monitoring and rate limits, budgets, sane defaults and requiring a reason for the bigger model (<a href="https://www.youtube.com/watch?v=BgLdvF7Qkh8&amp;t=771s" target="_blank" rel="noopener">12:51</a>–<a href="https://www.youtube.com/watch?v=BgLdvF7Qkh8&amp;t=934s" target="_blank" rel="noopener">15:34</a>)</li></ul></div></article><article class="it full" id="v-aGIUg8zKI8A" data-title="How a Trading Firm Ships New AI Models the Same Day - Noyan Tokgozoglu, Optiver" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=aGIUg8zKI8A" target="_blank" rel="noopener"><img src="'+d+'" srcset="'+N+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=aGIUg8zKI8A" target="_blank" rel="noopener">How a Trading Firm Ships New AI Models the Same Day - Noyan Tokgozoglu, Optiver</a></h3><div class="meta">AI Engineer · Noyan Tokgozoglu, head of AI Engineering, Optiver · uploaded 27 Oct, 12:30 PM IST · 23:23</div><div class="verdict v-skim"><b>Verdict:</b> skim from 7:06 — the same-day model rollout, meta harness and especially the spend fixes at 9:53 are concrete and well told, though gateway and cost-control ideas are well covered in the history.</div><div class="repeat">🔁 Repeat: &#39;AI for finance&#39; — seen 14 times before. New here: a market maker&#39;s view, where a rollout shows up in that day&#39;s P&amp;L, so missed opportunities are costly and decisions must be fast and measurable.</div><div class="repeat">🔁 Repeat: &#39;token costs / AI spend&#39; — seen 10 times before. New here: fresh sessions starting at 200k+ tokens of context, cut with MCP tool search, CLI wrappers around MCPs, cache tuning and team-set alerts and limits.</div><div class="repeat">🔁 Repeat: &#39;AI gateway&#39; — seen 4 times before. New here: an on-prem inference gateway (routing, per-model spend, budgets, provider failover) plus an agent gateway that acts as a single ledger of every agent.</div><div class="repeat">🔁 Repeat: &#39;harness engineering&#39; — seen 25 times before. New here: a &quot;meta harness&quot; layer where teams define portable harness configs across several supported harnesses.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 44 times before. New here: replaying tool calls through an MCP proxy with a per-call confidence for how well its world state can be restored to that point in time.</div><div class="repeat">🔁 Repeat: &#39;LLM releases / benchmarks&#39; — seen 42 times before. New here: not model news but the process of benchmarking each new frontier model on internal golden sets the day it ships.</div><div class="repeat">🔁 Repeat: &#39;vendor lock-in&#39; — seen 4 times before. New here: they left an inference-gateway vendor that put needed features &quot;on the road map&quot;.</div><div class="sh">Why a trading firm moves fast</div><ul><li><strong>P&amp;L in hours:</strong> Optiver makes 10M+ trades a day pricing 1M+ instruments across 10+ offices; the balance sheet is zeroed each morning, so a change rolled out to traders and quants shows its P&amp;L impact within hours, unlike his Apple experience of quarters. Missed opportunities (e.g. a hypothetical SpaceX AI IPO) are costly, hence a bias for action (<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=26s" target="_blank" rel="noopener">0:26</a>–<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=171s" target="_blank" rel="noopener">2:51</a>)</li><li><strong>Platform principles:</strong> Be modular for each new model or paradigm (loops, swarms, graphs), measure at every layer with internal benchmarks because their data differs from public ones, be self-service with good defaults for high-agency traders, forward-deploy AI engineers to sit with traders, and run everything on-prem; only third-party inference leaves, under zero-data-retention agreements (<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=174s" target="_blank" rel="noopener">2:54</a>–<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=308s" target="_blank" rel="noopener">5:08</a>)</li></ul><div class="sh">The platform</div><ul><li><strong>Stack:</strong> Third-party and self-hosted open models sit behind an inference gateway for routing, per-model spend, budgets and failover (&quot;any time that we&#39;re down… we&#39;re not making money&quot;). An agent platform has registered skills, plugins and tools plus per-team knowledge and memory, an agent gateway is the single ledger for agents and humans with shared identity management, and the surfaces are a web UI, an &quot;agent workbench&quot; for shareable team personas and a company-wide personal assistant (<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=327s" target="_blank" rel="noopener">5:27</a>–<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=419s" target="_blank" rel="noopener">6:59</a>)</li><li><strong>Same-day frontier models:</strong> A new public frontier model is benchmarked the same day on golden sets collected with partner trading teams, then wired into the gateway with cost controls and updated harnesses, backed by follow-the-sun support rotations and a recommendation note to staff (<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=426s" target="_blank" rel="noopener">7:06</a>–<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=506s" target="_blank" rel="noopener">8:26</a>)</li><li><strong>Model- and harness-agnostic:</strong> Some workloads must run in a fully on-prem DMZ, so everything goes through the gateway, every model interaction is logged into the eval system, and a meta-harness layer lets teams define portable harness configs that plug into their knowledge base, with knowledge mined from traces over time (<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=510s" target="_blank" rel="noopener">8:30</a>–<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=588s" target="_blank" rel="noopener">9:48</a>)</li></ul><div class="sh">Getting spend under control</div><ul><li><strong>What fixed it:</strong> Spend jumped at the December &quot;Claude Code moment&quot; and again with the summer&#39;s frontier releases, then came back under control. Fresh sessions were loading 200k+ tokens of context by default, so they added MCP tool search, CLIs wrapping MCPs, cache-invalidation and TTL tuning, and moved content from huge system prompts into the knowledge base; these savings grow as tokens get pricier (<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=593s" target="_blank" rel="noopener">9:53</a>–<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=731s" target="_blank" rel="noopener">12:11</a>)</li><li><strong>People manage their own budgets:</strong> Showing teams their spend and letting them set their own alerts and limits worked (&quot;they actually do a pretty good job&quot;), along with open-weight models that compete on token cost, routing to cheaper models, frontier-plan/small-model-implement splits and better retrieval; &quot;this is just about getting more ROI out of the same tokens&quot; (<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=746s" target="_blank" rel="noopener">12:26</a>–<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=830s" target="_blank" rel="noopener">13:50</a>)</li><li><strong>Meet users where they are:</strong> Instead of people&#39;s hacky web UIs and bespoke dev-box setups, they built a portal (sessions, chat, artifacts) that traders now send PRs to, adding collaborative editing, multiplayer rooms mixing people&#39;s agents and a Slack client (<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=834s" target="_blank" rel="noopener">13:54</a>–<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=930s" target="_blank" rel="noopener">15:30</a>)</li></ul><div class="sh">Q&amp;A</div><ul><li><strong>Eval replay and agent sprawl:</strong> Every tool call is OTel-logged into evals, but replaying, say, a Slack support bot on a new model needs past world state. Backtest data is easy to query at a point in time and Slack isn&#39;t, so each call gets a confidence score for how well it can be replayed through a proxy around the MCPs. Rather than merging agents into one bloated agent, they version agents and scope each to one measurable task that others call through the agent gateway. On build vs buy, vendors were slow to support on-prem and tend to lock you in (<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=1177s" target="_blank" rel="noopener">19:37</a>–<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=1269s" target="_blank" rel="noopener">21:09</a>), (<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=1296s" target="_blank" rel="noopener">21:36</a>–<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=1393s" target="_blank" rel="noopener">23:13</a>), (<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=1040s" target="_blank" rel="noopener">17:20</a>–<a href="https://www.youtube.com/watch?v=aGIUg8zKI8A&amp;t=1113s" target="_blank" rel="noopener">18:33</a>)</li></ul></div></article></div>',1))])}const C=u(I,[["render",j]]);export{G as __pageData,C as default};
